void ntfs_upcase_table(u16 *t) {
    for (u32 c = 0; c < 65536; c++) t[c] = (u16)c;
    for (u32 i = 0; i < sizeof runs / sizeof runs[0]; i++)
        for (u32 k = 0; k < runs[i].count; k++) {
            u32 c = runs[i].first + k * runs[i].step;
            t[c] = (u16)(c + (u32)runs[i].delta);
        }
}
